[{"order":1,"type":"heading","text":"Handling Responses in Angular: Observables and Promises"},{"order":2,"type":"paragraph","text":"Angular applications frequently interact with backend services to retrieve and manipulate data. This interaction is typically asynchronous, meaning the application doesn't wait for the response before continuing execution. Angular provides two primary mechanisms for handling asynchronous responses: Observables and Promises."},{"order":3,"type":"subheading","text":"Promises"},{"order":4,"type":"paragraph","text":"A Promise represents a single asynchronous operation that may or may not be completed yet, but eventually will be. It has three states: pending, fulfilled (resolved), or rejected. Promises are useful for handling single asynchronous operations."},{"order":5,"type":"code","text":"function getData(): Promise<any> {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      const data = { message: 'Data fetched successfully!' };
      resolve(data);
      // If there was an error:
      // reject('Error fetching data');
    }, 2000);
  });
}

getData()
  .then(data => {
    console.log('Data:', data);
  })
  .catch(error => {
    console.error('Error:', error);
  });"},{"order":6,"type":"bullet_point","text":"Use '.then()' to handle successful resolution of the Promise."},{"order":7,"type":"bullet_point","text":"Use '.catch()' to handle rejections (errors) of the Promise."},{"order":8,"type":"subheading","text":"Observables"},{"order":9,"type":"paragraph","text":"Observables, provided by RxJS (Reactive Extensions for JavaScript), are more powerful than Promises. They represent a stream of data that can emit multiple values over time. Observables are ideal for handling multiple asynchronous events, such as user input, HTTP requests, and WebSocket messages."},{"order":10,"type":"code","text":"import { Observable } from 'rxjs';

function getDataObservable(): Observable<any> {
  return new Observable(observer => {
    setTimeout(() => {
      observer.next({ message: 'First data emission!' });
    }, 1000);

    setTimeout(() => {
      observer.next({ message: 'Second data emission!' });
    }, 2000);

    setTimeout(() => {
      observer.complete(); // Signal that no more data will be emitted
    }, 3000);

    // If there was an error:
    // observer.error('An error occurred');
  });
}

const subscription = getDataObservable().subscribe(
  data => {
    console.log('Data:', data);
  },
  error => {
    console.error('Error:', error);
  },
  () => {
    console.log('Observable completed');
  }
);

// To unsubscribe (e.g., in ngOnDestroy):
// subscription.unsubscribe();"},{"order":11,"type":"bullet_point","text":"Use '.subscribe()' to listen for data emissions, errors, and completion of the Observable."},{"order":12,"type":"bullet_point","text":"The '.next()' method emits a new value to the subscribers."},{"order":13,"type":"bullet_point","text":"The '.error()' method signals an error to the subscribers."},{"order":14,"type":"bullet_point","text":"The '.complete()' method signals that the Observable has finished emitting values."},{"order":15,"type":"bullet_point","text":"Remember to unsubscribe from Observables to prevent memory leaks, especially in components that are frequently created and destroyed. Use the '.unsubscribe()' method on the subscription object."},{"order":16,"type":"subheading","text":"HTTP Requests with HttpClient"},{"order":17,"type":"paragraph","text":"Angular's HttpClient service uses Observables to handle HTTP requests. This allows you to easily retrieve data from APIs and handle responses."},{"order":18,"type":"code","text":"import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  private apiUrl = 'https://jsonplaceholder.typicode.com/todos/1';

  constructor(private http: HttpClient) { }

  getData(): Observable<any> {
    return this.http.get<any>(this.apiUrl);
  }
}

// In your component:
import { DataService } from './data.service';

constructor(private dataService: DataService) { }

ngOnInit(): void {
  this.dataService.getData().subscribe(
    data => {
      console.log('Data from API:', data);
    },
    error => {
      console.error('Error fetching data:', error);
    }
  );
}"},{"order":19,"type":"paragraph","text":"The HttpClient's 'get', 'post', 'put', 'delete', etc. methods return Observables. You subscribe to these Observables to handle the response from the server."},{"order":20,"type":"subheading","text":"Error Handling"},{"order":21,"type":"paragraph","text":"Proper error handling is crucial for robust applications. Both Promises and Observables provide mechanisms for handling errors."},{"order":22,"type":"bullet_point","text":"For Promises, use the '.catch()' method."},{"order":23,"type":"bullet_point","text":"For Observables, provide an error callback function to the '.subscribe()' method."},{"order":24,"type":"paragraph","text":"You can also use RxJS operators like 'catchError' to handle errors within the Observable stream."},{"order":25,"type":"code","text":"import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable, throwError } from 'rxjs';
import { catchError } from 'rxjs/operators';

@Injectable({
  providedIn: 'root'
})
export class DataService {
  private apiUrl = 'https://jsonplaceholder.typicode.com/todos/1';

  constructor(private http: HttpClient) { }

  getData(): Observable<any> {
    return this.http.get<any>(this.apiUrl).pipe(
      catchError(error => {
        console.error('Error occurred:', error);
        return throwError(() => new Error('Something bad happened; please try again later.'));
      })
    );
  }
}"},{"order":26,"type":"subheading","text":"Choosing Between Observables and Promises"},{"order":27,"type":"paragraph","text":"Generally, Observables are preferred in Angular due to their flexibility and power. However, Promises can be suitable for simple, single asynchronous operations where you only need a single value."},{"order":28,"type":"bullet_point","text":"Use Promises for single asynchronous operations (e.g., a simple API call that returns a single value)."},{"order":29,"type":"bullet_point","text":"Use Observables for streams of data, multiple asynchronous events, or when you need more control over the asynchronous operation (e.g., cancellation, retry)."}]
